import { memo, useState } from "react";
import { Button, Divider, Grid, InputText, Link, Stack, Text } from "@kit/index.js";
import { TrackingScope, Translate, useTranslation, withTracking } from "travel-platform";
import styles from "./Footer.module.css";

const COLUMNS = [
    ["footer.countries", "footer.regions", "footer.cities", "footer.districts", "footer.airports", "footer.hotels", "footer.places"],
    ["footer.homes", "footer.apartments", "footer.resorts", "footer.villas", "footer.hostels", "footer.guest_houses", "footer.unique"],
    ["footer.reviews", "footer.discover", "footer.articles", "footer.seasonal", "footer.traveller_awards"],
    ["footer.car_hire", "footer.flight_finder", "footer.restaurants", "footer.agents", "footer.coronavirus"],
    ["footer.service", "footer.partner_help", "footer.partner_extranet", "footer.affiliate", "footer.business"],
];
const LEGAL = ["footer.about", "footer.careers", "footer.sustainability", "footer.press", "footer.safety", "footer.investors", "footer.terms", "footer.privacy", "footer.modern_slavery", "footer.human_rights", "footer.contact", "footer.content_guidelines", "footer.dispute"];

const TrackedLink = withTracking(Link, "footer.link");

const FooterLink = memo(function FooterLink({ href, children, variant, className }) {
    return <li><TrackedLink href={href} variant={variant} className={className} trackingData={{ href }}>{children}</TrackedLink></li>;
});

function slug(key) {
    return key.replace("footer.", "").replace(/_/g, "-");
}

function Subscribe() {
    const t = useTranslation();
    const [email, setEmail] = useState("");
    return (
        <section className={styles.subscribe}>
            <Text as="h2" variant="headline_2" color="inverted"><Translate id="footer.subscribe_title" /></Text>
            <Text variant="body_1" color="inverted"><Translate id="footer.subscribe_body" /></Text>
            <form className={styles.subscribeForm} onSubmit={(e) => e.preventDefault()}>
                <InputText label={t("footer.subscribe_placeholder")} placeholder={t("footer.subscribe_placeholder")} value={email} onChange={(e) => setEmail(e.target.value)} className={styles.email} />
                <Button type="submit" size="large"><Translate id="footer.subscribe_cta" /></Button>
            </form>
        </section>
    );
}

function FooterColumn({ keys }) {
    return (
        <ul className={styles.column}>
            {keys.map((key) => <FooterLink key={key} href={`${slug(key)}.html`} className={styles.link}><Translate id={key} /></FooterLink>)}
        </ul>
    );
}

function DestinationIndex({ destinations }) {
    return (
        <nav className={styles.index} aria-label="Popular destinations">
            {destinations.map((group) => (
                <div key={group.title} className={styles.indexGroup}>
                    <Text as="h3" variant="strong_2">{group.title}</Text>
                    <ul className={styles.indexList}>
                        {group.items.map((item) => <FooterLink key={item} href={`destination/${encodeURIComponent(item.toLowerCase())}.html`} variant="small_1">{item}</FooterLink>)}
                    </ul>
                </div>
            ))}
        </nav>
    );
}

const COUNTRIES = ["Vellmark", "Aurenne", "Castival", "Doralia", "Estrane", "Fennor", "Galvary", "Heloise", "Istria Nova", "Jurenne", "Kalmora", "Lusine", "Morvane", "Norvell", "Ostrava Vale", "Pellune", "Quintara", "Rosmere", "Sylvane", "Tarrow", "Ulmeria", "Valdessa", "Wendmoor", "Yselle", "Zarova", "Altmere", "Brenvale", "Corsaine", "Delmont", "Eriva", "Faloria", "Grenmark", "Hollis", "Ivermont", "Jessaline", "Korvin", "Lorrel", "Marivelle", "Nessa", "Orlaine"];

const Country = memo(function Country({ name }) {
    return <FooterLink href={`country/${name.toLowerCase().replace(/ /g, "-")}.html`} variant="small_1">{name}</FooterLink>;
});

function CountrySelector() {
    return (
        <section className={styles.countries}>
            <Text as="h3" variant="strong_2"><Translate id="footer.countries" /></Text>
            <ul className={styles.countryList}>{COUNTRIES.map((name) => <Country key={name} name={name} />)}</ul>
        </section>
    );
}

export default function FooterContent({ destinations = [], year = 2026 }) {
    const t = useTranslation();
    return (
        <TrackingScope surface="footer">
            <footer className={styles.footer} data-testid="footer">
                <Subscribe />
                <div className={styles.inner}>
                    <Stack direction="row" gap={4} justifyContent="center" className={styles.utility}>
                        <Link href="m/" className={styles.utilityLink}><Translate id="footer.mobile" /></Link>
                        <Link href="account/bookings.html" className={styles.utilityLink}><Translate id="footer.manage" /></Link>
                        <Link href="help/" className={styles.utilityLink}><Translate id="footer.service" /></Link>
                        <Link href="affiliates/" className={styles.utilityLink}><Translate id="footer.affiliate" /></Link>
                        <Link href="business/" className={styles.utilityLink}><Translate id="footer.business" /></Link>
                    </Stack>
                    <DestinationIndex destinations={destinations} />
                    <CountrySelector />
                    <Divider />
                    <Grid columns={{ base: 2, medium: 3, large: 5 }} gap={6} className={styles.columns}>
                        {COLUMNS.map((keys, i) => <FooterColumn key={i} keys={keys} />)}
                    </Grid>
                    <ul className={styles.legal}>
                        {LEGAL.map((key) => <FooterLink key={key} href={`about/${slug(key)}.html`} variant="small_1"><Translate id={key} /></FooterLink>)}
                    </ul>
                    <Text variant="small_1" color="alt" align="center">{t("footer.copyright", { year })}</Text>
                </div>
            </footer>
        </TrackingScope>
    );
}
